import{_ as i,a as o,c as a,ac as l}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","link":"/systems/linux/common-commands-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","link":"/systems/linux/common-commands-part-02"}},"headers":[],"relativePath":"systems/linux/common-commands-part-01.md","filePath":"systems/linux/common-commands-part-01.md"}'),u={name:"systems/linux/common-commands-part-01.md"};function e(r,t,m,n,s,d){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="linux-常用命令-用途、参数与操作边界-·-linux-基础命令" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · Linux 基础命令 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-linux-基础命令" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · Linux 基础命令&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="linux-常用命令-用途、参数与操作边界" tabindex="-1">Linux 常用命令：用途、参数与操作边界 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 {#linux-常用命令-用途、参数与操作边界}&quot;">​</a></h2><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><table tabindex="0"><thead><tr><th>要做什么</th><th>主速查</th></tr></thead><tbody><tr><td>文件与目录</td><td><a href="/systems/linux/common-commands-part-04#part-2-浏览、创建与移动文件">浏览、创建与移动</a></td></tr><tr><td>查找和读日志</td><td><a href="/systems/linux/common-commands-part-04#part-2-搜索文件与命令">搜索</a>、<a href="/systems/linux/common-commands-part-04#part-2-读取文件与日志">读取</a>、<a href="/systems/linux/common-commands-part-04#part-2-文本筛选、统计与比较">文本处理</a></td></tr><tr><td>身份和权限</td><td><a href="/systems/linux/common-commands-part-05#part-2-账号、权限与属性">账号、权限与属性</a></td></tr><tr><td>归档与数据</td><td><a href="/systems/linux/common-commands-part-05#part-2-打包与压缩">打包压缩</a>、<a href="/systems/linux/common-commands-part-05#part-2-磁盘容量与挂载">容量挂载</a>、<a href="/systems/linux/common-commands-part-06#part-2-备份与同步">备份同步</a></td></tr><tr><td>软件与网络</td><td><a href="/systems/linux/common-commands-part-06#part-2-按发行版选择包管理器">包管理器</a>、<a href="/systems/linux/common-commands-part-06#part-2-网络接口与路由">网络接口与路由</a></td></tr><tr><td>进程与服务</td><td><a href="/systems/linux/common-commands-part-02#part-1-top-实时显示进程状态">实时状态</a>、<a href="/systems/linux/common-commands-part-03#part-1-ps-列出当前系统进程">进程列表</a>、<a href="/systems/linux/common-commands-part-03#part-1-kill-结束某个进程">停止边界</a></td></tr></tbody></table><p><strong>基础命令逐条解释（保留旧章节入口）</strong></p><h2 id="part-1" tabindex="-1">Linux 基础命令 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Linux 基础命令 {#part-1}&quot;">​</a></h2><p><span id="part-1-linux-基础命令-1"></span></p><p>Linux 是一种典型的 Unix 类操作系统，基于命令行操作，以下是一些常用的 Linux 基础命令：</p><ol><li>ls：列出目录内容</li><li>cd：切换目录</li><li>mkdir：创建新目录</li><li>rm：删除文件或目录</li><li>cp：复制文件或目录</li><li>mv：移动文件或目录</li><li>touch：创建新文件</li><li>cat：连接、显示文件内容</li><li>grep：文本搜索工具</li><li>ping：测试网络连接</li><li>ifconfig：查看和配置网络接口状态</li><li>top：实时显示进程状态</li><li>ps：列出当前系统进程</li><li>kill：结束某个进程</li><li>tar：打包或解压缩文件</li></ol><p>以上只是常用命令的部分，还有很多其他的 Linux 命令可以使用。</p><h3 id="part-1-ls-列出目录内容" tabindex="-1">ls 列出目录内容 <a class="header-anchor" href="#part-1-ls-列出目录内容" aria-label="Permalink to &quot;ls 列出目录内容 {#part-1-ls-列出目录内容}&quot;">​</a></h3><p>&quot;ls&quot; 是一个常用的命令，用于显示当前工作目录中的文件和子目录列表。以下是 &quot;ls&quot; 命令的详细解释：</p><ul><li>格式：ls [选项] [文件/目录]</li><li>选项：ls 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-l：以长格式列表方式显示文件和目录（包括权限、拥有者、大小、修改时间等信息）</li><li>-a：显示所有文件和目录，包括隐藏文件和目录</li><li>-h：人性化地显示文件和目录大小，例如使用 MB、GB 等单位</li><li>-r：反向排序输出结果</li><li>-t：按时间排序输出结果，最新的文件或目录将排在前面</li></ul></li><li>文件/目录：可以指定一个或多个文件或目录来进行查看，如果不指定，则默认为当前工作目录。</li></ul><p>举个例子，如果要查看当前工作目录下的所有文件和目录，可以输入 &quot;ls&quot; 命令，在命令行界面上会列出所有文件和子目录的名称。如果要查看详细的信息，可以输入 &quot;ls -l&quot; 命令，会列出每个文件和目录的权限、拥有者、大小、修改时间等信息。</p><h3 id="part-1-cd-切换目录" tabindex="-1">cd 切换目录 <a class="header-anchor" href="#part-1-cd-切换目录" aria-label="Permalink to &quot;cd 切换目录 {#part-1-cd-切换目录}&quot;">​</a></h3><p>&quot;cd&quot; 命令用于更改当前工作目录。以下是 &quot;cd&quot; 命令的详解：</p><ul><li>格式：cd [目录路径]</li><li>目录路径：要切换到的目录路径，可以是绝对路径或相对路径。如果不指定目录路径，则默认更改为当前用户的主目录。</li></ul><p>举个例子，如果当前工作目录为 &quot;/home/user1/Documents&quot;，如果要切换到该用户的主目录 &quot;/home/user1&quot;，可以输入 &quot;cd&quot; 命令或 &quot;cd ~&quot; 命令；如果要切换到 &quot;/home/user1/Desktop&quot; 目录，可以输入 &quot;cd Desktop&quot; 或 &quot;cd /home/user1/Desktop&quot; 命令。</p><p>此外，还有一些特殊符号可以在 &quot;cd&quot; 命令中使用来快速导航：</p><ul><li>. ：代表当前目录，例如 &quot;cd .&quot; 命令不会进行任何操作。</li><li>.. ：代表上级目录，例如 &quot;cd ..&quot; 命令可以将当前目录切换到其父目录。</li><li><code>-</code> ：代表上一个工作目录，例如 &quot;cd -&quot; 命令可以切换回之前的工作目录。</li></ul><p>需要注意的是，如果指定的目录不存在或没有访问权限，&quot;cd&quot; 命令将会失败并输出错误信息。因此，在使用 &quot;cd&quot; 命令时需要确保目录存在并且有正确的访问权限。</p><h3 id="part-1-mkdir-创建新目录" tabindex="-1">mkdir 创建新目录 <a class="header-anchor" href="#part-1-mkdir-创建新目录" aria-label="Permalink to &quot;mkdir 创建新目录 {#part-1-mkdir-创建新目录}&quot;">​</a></h3><p>&quot;mkdir&quot; 命令用于创建新的目录。以下是 &quot;mkdir&quot; 命令的详解：</p><ul><li>格式：mkdir [选项] 目录名</li><li>选项：mkdir 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-p：递归地创建目录和子目录，例如可以使用 &quot;mkdir -p dir1/dir2/dir3&quot; 一次性创建多级目录。</li><li>-m：指定新创建目录的权限，例如可以使用 &quot;mkdir -m 755 dirname&quot; 创建新目录并将其权限设置为 755。</li></ul></li><li>目录名：要创建的目录名称。</li></ul><p>举个例子，如果想在当前工作目录下创建一个名为 &quot;test&quot; 的新目录，可以输入 &quot;mkdir test&quot; 命令。如果想要一次性创建多级目录，可以使用 &quot;mkdir -p dir1/dir2/dir3&quot; 命令来创建名为 &quot;dir1/dir2/dir3&quot; 的目录树。如果需要指定新目录的权限，则可以使用 &quot;mkdir -m 755 dirname&quot; 命令，并将目录权限设置为 755。</p><p>需要注意的是，如果目录已经存在，&quot;mkdir&quot; 命令将会失败并输出错误信息。因此，在使用 &quot;mkdir&quot; 命令时需要确保目录不存在或者使用 &quot;-p&quot; 选项递归创建目录。</p><h3 id="part-1-rm-删除文件或目录" tabindex="-1">rm 删除文件或目录 <a class="header-anchor" href="#part-1-rm-删除文件或目录" aria-label="Permalink to &quot;rm 删除文件或目录 {#part-1-rm-删除文件或目录}&quot;">​</a></h3><p>&quot;rm&quot; 命令用于删除文件或目录。以下是 &quot;rm&quot; 命令的详解：</p><ul><li>格式：rm [选项] 文件/目录</li><li>选项：rm 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-f：强制删除文件或目录，不提示确认。</li><li>-r：递归删除目录及其子目录和文件。</li><li>-i：交互式删除，删除每个文件或目录前都会提示确认。</li></ul></li><li>文件/目录：要删除的文件或目录名称。</li></ul><p>举个例子，如果要删除当前工作目录下名为 &quot;test.txt&quot; 的文件，可以输入 &quot;rm test.txt&quot; 命令。如果要删除一个目录及其所有子目录和文件，可以使用 &quot;rm -r dirname&quot; 命令，注意需要谨慎操作以避免误删重要数据。如果需要在删除前进行确认，可以使用 &quot;-i&quot; 选项，例如 &quot;rm -i filename&quot; 命令会在删除文件前提示确认。</p><p>需要注意的是，删除文件或目录时需要确保有足够的权限，并且慎重考虑是否真的需要删除它们，因为一旦删除将无法恢复。在使用 &quot;rm&quot; 命令时建议先进行备份并且谨慎操作。</p><h3 id="part-1-cp-复制文件或目录" tabindex="-1">cp 复制文件或目录 <a class="header-anchor" href="#part-1-cp-复制文件或目录" aria-label="Permalink to &quot;cp 复制文件或目录 {#part-1-cp-复制文件或目录}&quot;">​</a></h3><p>&quot;cp&quot; 命令用于复制文件或目录。以下是 &quot;cp&quot; 命令的详解：</p><ul><li>格式：cp [选项] 源文件/目录 目标文件/目录</li><li>选项：cp 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-r：递归复制目录及其子目录和文件。</li><li>-i：交互式复制，复制每个文件或目录前都会提示确认。</li><li>-p：保留源文件或目录的权限、所有权和时间戳等信息。</li></ul></li><li>源文件/目录：要复制的源文件或目录名称。</li><li>目标文件/目录：要将源文件或目录复制到的目标位置。</li></ul><p>举个例子，如果要将当前工作目录下名为 &quot;test.txt&quot; 的文件复制到 /home/user1/ 目录中，可以输入 &quot;cp test.txt /home/user1/&quot; 命令。如果要复制一个目录及其所有子目录和文件，可以使用 &quot;cp -r sourcedir destdir&quot; 命令。如果需要在复制前进行确认，可以使用 &quot;-i&quot; 选项，例如 &quot;cp -i filename /path/to/destination/&quot; 命令会在复制文件前提示确认。如果需要保留源文件或目录的权限和所有权等信息，可以使用 &quot;-p&quot; 选项，例如 &quot;cp -rp sourcedir destdir&quot; 命令会递归复制目录并保留其所有权、权限和时间戳等信息。</p><p>需要注意的是，在复制目录时，需要使用 &quot;-r&quot; 选项递归复制子目录和文件，并确保复制到的目标位置具有足够的权限。在使用 &quot;cp&quot; 命令时建议谨慎操作以避免误操作。</p><h3 id="part-1-mv-移动文件或目录" tabindex="-1">mv 移动文件或目录 <a class="header-anchor" href="#part-1-mv-移动文件或目录" aria-label="Permalink to &quot;mv 移动文件或目录 {#part-1-mv-移动文件或目录}&quot;">​</a></h3><p>&quot;mv&quot; 命令用于移动或重命名文件或目录。以下是 &quot;mv&quot; 命令的详解：</p><ul><li>格式：mv [选项] 源文件/目录 目标文件/目录</li><li>选项：mv 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-i：交互式移动或重命名，移动或重命名每个文件或目录前都会提示确认。</li><li>-f：强制移动或重命名，不提示确认。</li></ul></li><li>源文件/目录：要移动或重命名的源文件或目录名称。</li><li>目标文件/目录：要将源文件或目录移动到的目标位置，或者要将源文件或目录重命名为的新名称。</li></ul><p>举个例子，如果要将当前工作目录下名为 &quot;test.txt&quot; 的文件移动到 /home/user1/ 目录中，可以输入 &quot;mv test.txt /home/user1/&quot; 命令。如果要将一个目录及其所有子目录和文件移动到另一个位置，可以使用 &quot;mv sourcedir destdir&quot; 命令。如果需要将文件或目录重命名，可以将目标位置指定为新名称，例如 &quot;mv oldname newname&quot; 命令将文件或目录 &quot;oldname&quot; 重命名为 &quot;newname&quot;。</p><p>需要注意的是，在移动或重命名文件或目录时，需要确保源文件或目录存在，并且目标位置具有足够的权限。在使用 &quot;mv&quot; 命令时建议谨慎操作以避免误操作，并且不要将文件移动到其他程序正在使用的目录中以避免出现意外错误。</p>',43)])])}const q=i(u,[["render",e]]);export{c as __pageData,q as default};
